<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Features\Access\UserConsentPurposes\Domain\Gateway;

use Civi\Lughauth\Features\Access\UserConsentPurposes\Domain\UserConsentPurposes;

class UserConsentPurposesCursor
{
    public function __construct(
        private int $limit,
        private ?string $sinceUid = null,
    ) {
    }
    public function next(UserConsentPurposes $userConsentPurposes, ?int $size): UserConsentPurposesCursor
    {
        $next = clone $this;
        $next->sinceUid = $userConsentPurposes->uid();
        $next->limit = $size ?? $this->limit;
        return $next;
    }
    public function limit(): int
    {
        return $this->limit;
    }
    public function sinceUid(): ?string
    {
        return $this->sinceUid;
    }
}
